import{_ as n,w as a,s as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"如何备份一个磁盘分区 | LCTT x X-CMD","titleTemplate":false,"description":"如何备份一个磁盘分区 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何备份一个磁盘分区 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何备份一个磁盘分区 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170112 Partition Backup","title":"如何备份一个磁盘分区","tag":"201705","desc":""},"relativePath":"201705/20170112 Partition Backup.md","filePath":"[post].md"}'),e={name:"201705/20170112 Partition Backup.md"};function i(c,s,d,t,o,r){return a(),p("div",null,[...s[0]||(s[0]=[l('<h1 id="如何备份一个磁盘分区" tabindex="-1">如何备份一个磁盘分区 <a class="header-anchor" href="#如何备份一个磁盘分区" aria-label="Permalink to “如何备份一个磁盘分区”">​</a></h1><p>通常你可能会把数据放在一个分区上，有时候可能需要对该设备或者上面的一个分区进行备份。树莓派用户为了可引导 SD 卡当然有这个需求。其它小体积计算机的用户也会发现这非常有用。有时候设备看起来要出现故障时最好快速做个备份。</p><p>进行本文中的实验你需要一个叫 <code>dcfldd</code> 的工具。</p><h3 id="dcfldd-工具" tabindex="-1">dcfldd 工具 <a class="header-anchor" href="#dcfldd-工具" aria-label="Permalink to “dcfldd 工具”">​</a></h3><p>该工具是 coreutils 软件包中 <code>dd</code> 工具的增强版。<code>dcfldd</code> 是 Nicholas Harbour 在美国国防部计算机取证实验室（DCFL）工作期间研发的。该工具的名字也基于他工作的地方 - <code>dcfldd</code>。</p><p>对于仍然在使用 CoreUtils 8.23 或更低版本的系统，并没有一个可以轻松查看正在创建副本的进度的选项。有时候看起来就像什么都没有发生，以至于你就想取消掉备份。</p><p><strong>注意：</strong>如果你使用 8.24 或更新版本的 <code>dd</code> 工具，你就不需要使用 <code>dcfldd</code>，只需要用 <code>dd</code> 替换 <code>dcfldd</code> 即可。所有其它参数仍然适用。</p><p>在 Debian 系统上你只需要在 Package Manager 中搜索 <code>dcfldd</code>。你也可以打开一个终端然后输入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install dcfldd</span></span></code></pre></div><p>对于 Red Hat 系统，可以用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /tmp  </span></span>\n<span class="line"><span>wget dl.fedoraproject.org/pub/epel/6/i386/dcfldd-1.3.4.1-4.el6.i686.rpm  </span></span>\n<span class="line"><span>sudo yum install dcfldd-1.3.4.1-4.el6.i686.rpm  </span></span>\n<span class="line"><span>dcfldd --version</span></span></code></pre></div><p><strong>注意：</strong> 上面的命令安装的是 32 位版本。对于 64 位版本，使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /tmp  </span></span>\n<span class="line"><span>wget dl.fedoraproject.org/pub/epel/6/x86_64/dcfldd-1.3.4.1-4.el6.x86_64.rpm  </span></span>\n<span class="line"><span>sudo yum install dcfldd-1.3.4.1-4.el6.x86_64.rpm  </span></span>\n<span class="line"><span>dcfldd --version</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>每组命令中的最后一个语句会列出 `dcfldd` 的版本并显示该命令文件已经被加载。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：**确保你以 root 用户执行 `dd` 或者 `dcfldd` 命令。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>安装完该工具后你就可以继续使用它备份和恢复分区。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 备份分区</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>备份设备的时候可以备份整个设备也可以只是其中的一个分区。如果设备有多个分区，我们可以分别备份每个分区。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>在进行备份之前，先让我们来看一下设备和分区的区别。假设我们有一个已经被格式化为一个大磁盘的 SD 卡。这个 SD 卡只有一个分区。如果空间被切分使得 SD 卡看起来是两个设备，那么它就有两个分区。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>假设我们有一个树莓派中的 SD 卡。SD 卡容量为 8 GB，有两个分区。第一个分区存放 BerryBoot 启动引导器。第二个分区存放 Kali（LCTT 译注：Kali Linux 是一个 Debian 派生的 Linux 发行版）。现在已经没有可用的空间用来安装第二个操作系统。我们使用大小为 16 GB 的第二个 SD 卡，但拷贝到第二个 SD 卡之前，第一个 SD 卡必须先备份。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>要备份第一个 SD 卡我们需要备份设备 `/dev/sdc`。进行备份的命令如下所示：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd if=/dev/sdc of=/tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>备份包括输入文件（`if`）以及被设置为 `/tmp` 目录下名为 `SD-Card-Backup.img` 的输出文件（`of`）。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>`dd` 和 `dcfldd` 默认都是每次读写文件中的一个块。通过上述命令，它可以一次默认读写 512 个字节。记住，该复制是一个精准的拷贝 - 逐位逐字节。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>默认的 512 个字节可以通过块大小参数 - `bs=` 更改。例如，要每次读写 1 兆字节，参数为 `bs=1M`。使用以下所用的缩写可以设置不同大小：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>*   b – 512 字节</span></span>\n<span class="line"><span>*   KB – 1000 字节</span></span>\n<span class="line"><span>*   K – 1024 字节</span></span>\n<span class="line"><span>*   MB – 1000x1000 字节</span></span>\n<span class="line"><span>*   M – 1024x1024 字节</span></span>\n<span class="line"><span>*   GB – 1000x1000x1000 字节</span></span>\n<span class="line"><span>*   G – 1024x1024x1024 字节</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>你也可以单独指定读和写的块大小。要指定读块的大小使用 `ibs=`。要指定写块的大小使用 `obs=`。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>我使用三种不同的块大小做了一个 120 MB 分区的备份测试。第一次使用默认的 512 字节，它用了 7 秒钟。第二次块大小为 1024 K，它用时 2 秒。第三次块大小是 2048 K，它用时 3 秒。用时会随系统以及其它硬件实现的不同而变化，但通常来说更大的块大小会比默认的稍微快一点。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>完成备份后，你还需要知道如何把数据恢复到设备中。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 恢复分区</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>现在我们已经有了一个备份点，假设数据可能被损毁了或者由于某些原因需要进行恢复。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>命令和备份时相同，只是源和目标相反。对于上面的例子，命令会变为：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd of=/dev/sdc if=/tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>这里，镜像文件被用作输入文件（`if`）而设备（sdc）被用作输出文件（`of`）。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：** 要记住输出设备会被重写，它上面的所有数据都会丢失。通常来说在恢复数据之前最好用 GParted 删除 SD 卡上的所有分区。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>假如你在使用多个 SD 卡，例如多个树莓派主板，你可以一次性写多块 SD 卡。为了做到这点，你需要知道系统中卡的 ID。例如，假设我们想把镜像 `BerryBoot.img` 拷贝到两个 SD 卡。SD 卡分别是 `/dev/sdc` 和 `/dev/sdd`。下面的命令在显示进度时每次读写 1 MB 的块。命令如下：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd if=BerryBoot.img bs=1M status=progress | tee &gt;(dcfldd of=/dev/sdc) | dcfldd of=/dev/sdd</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>在这个命令中，第一个 `dcfldd` 指定输入文件并把块大小设置为 1 MB。`status` 参数被设置为显示进度。然后输入通过管道 `|`传输给命令 `tee`。`tee` 用于将输入分发到多个地方。第一个输出是到命令 `dcfldd of=/dev/sdc`。命令被放到小括号内被作为一个命令执行。我们还需要最后一个管道 `|`，否则命令 `tee` 会把信息发送到 `stdout` （屏幕）。因此，最后的输出是被发送到命令  `dcfldd of=/dev/sdd`。如果你有第三个 SD 卡，甚至更多，只需要添加另外的重定向和命令，类似 `&gt;(dcfldd of=/dev/sde`。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：**记住最后一个命令必须在管道 `|` 后面。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>必须验证写的数据确保数据是正确的。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 验证数据</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>一旦创建了一个镜像或者恢复了一个备份，你可以验证这些写入的数据。要验证数据，你会使用名为 `diff` 的另一个不同程序。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>使用 `diff` ，你需要指定镜像文件的位置以及系统中拷贝自或写入的物理媒介。你可以在创建备份或者恢复了一个镜像之后使用 `diff` 命令。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>该命令有两个参数。第一个是物理媒介，第二个是镜像文件名称。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>对于例子 `dcfldd of=/dev/sdc if=/tmp/SD-Card-Backup.img`，对应的 `diff` 命令是：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>diff /dev/sdc /tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>如果镜像和物理设备有任何的不同，你会被告知。如果没有显示任何信息，那么数据就验证为完全相同。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>确保数据完全一致是验证备份和恢复完整性的关键。进行备份时需要注意的一个主要问题是镜像大小。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 分割镜像</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>假设你想要备份一个 16GB 的 SD 卡。镜像文件大小会大概相同。如果你只能把它备份到 FAT32 分区会怎样呢？FAT32 最大文件大小限制是 4 GB。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>必须做的是文件必须被切分为 4 GB 的分片。通过管道 `|` 将数据传输给 `split` 命令可以切分正在被写的镜像文件。 </span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>创建备份的方法相同，但命令会包括管道和切分命令。示例备份命令为 `dcfldd if=/dev/sdc of=/tmp/SD-Card-Backup.img` ，其切分文件的新命令如下：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd if=/dev/sdc | split -b 4000MB - /tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：** 大小后缀和对 `dd` 及 `dcfldd` 命令的意义相同。 `split` 命令中的破折号用于将通过管道从 `dcfldd` 命令传输过来的数据填充到输入文件。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>文件会被保存为 `SD-Card-Backup.imgaa` 和 `SD-Card-Backup.imgab`，如此类推。如果你担心文件大小太接近 4 GB 的限制，可以试着用 3500MB。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>将文件恢复到设备也很简单。你使用 `cat` 命令将它们连接起来然后像下面这样用 `dcfldd` 写输出：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>cat /tmp/SD-Card-Backup.img* | dcfldd of=/dev/sdc</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>你可以在命令中 `dcfldd` 部分包含任何需要的参数。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>我希望你了解并能执行任何需要的数据备份和恢复，正如 SD 卡和类似设备所需的那样。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>--------------------------------------------------------------------------------</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>via: https://www.linuxforum.com/threads/partition-backup.3638/</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>作者：[Jarret][a]</span></span>\n<span class="line"><span>译者：[ictlyh](https://github.com/ictlyh)</span></span>\n<span class="line"><span>校对：[jasminepeng](https://github.com/jasminepeng)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>本文由 [LCTT](https://github.com/LCTT/TranslateProject) 原创编译，[Linux中国](https://linux.cn/) 荣誉推出</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>[a]:https://www.linuxforum.com/members/jarret.268/</span></span></code></pre></div>',13)])])}const m=n(e,[["render",i]]);export{h as __pageData,m as default};
